const GAS_URL='https://script.google.com/macros/s/AKfycbzjGMdPWMaGTUfkPNZxR0FLJCnyfk-YbfWomJzr77sasuaiHQXrbwRBTqRTuUyrYMko/exec';
const register=!!document.querySelector('#registerForm');
const form=document.querySelector(register?'#registerForm':'#loginForm');
const feedback=document.createElement('p');feedback.className='authmessage';feedback.setAttribute('role','status');form.after(feedback);
let pending=null,busy=false;
async function api(action,payload={}){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(GAS_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...payload}),signal:controller.signal});const text=await response.text();let result;try{result=JSON.parse(text);}catch{throw Error('Apps Script ยังไม่พร้อมใช้งาน กรุณาติดตั้ง Code.gs และ Deploy เวอร์ชันใหม่');}if(!result.ok)throw Error(result.error||'ทำรายการไม่สำเร็จ');return result.data;}catch(error){if(error.name==='AbortError')throw Error('ระบบตอบกลับช้า กรุณาตรวจอีเมลก่อนขอรหัสใหม่');if(error instanceof TypeError)throw Error('เชื่อม Apps Script ไม่ได้ กรุณาตรวจการ Deploy และสิทธิ์ Anyone');throw error;}finally{clearTimeout(timer);}}
function validate(){let valid=true;const fields=register?['fullName','nickname','studentId','email']:['email'];fields.forEach(id=>{const input=document.querySelector('#'+id),error=document.querySelector('#'+id+'Error');input.value=input.value.trim();if(error)error.hidden=true;input.removeAttribute('aria-invalid');document.querySelector('#'+id+'Wrap')?.classList.remove('invalid');if(!input.validity.valid){valid=false;input.setAttribute('aria-invalid','true');document.querySelector('#'+id+'Wrap')?.classList.add('invalid');if(error){error.textContent=input.validity.valueMissing?'กรุณากรอกข้อมูลช่องนี้':id==='email'?'กรุณากรอกอีเมลให้ถูกต้อง':'กรุณากรอกรหัสนักศึกษาเป็นตัวเลข';error.hidden=false;}}});return valid;}
form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!validate())return;const button=form.querySelector('[type="submit"]');busy=true;button.disabled=true;feedback.textContent='กำลังส่งรหัสยืนยัน…';try{pending={email:document.querySelector('#email').value.toLowerCase(),register};if(register)Object.assign(pending,{name:document.querySelector('#fullName').value,nickname:document.querySelector('#nickname').value,studentId:document.querySelector('#studentId').value});await api('requestOtp',pending);feedback.textContent='ส่งรหัสยืนยันแล้ว กรุณาตรวจกล่องจดหมายและอีเมลขยะ';showOtp();}catch(error){feedback.textContent=error.message;}finally{busy=false;button.disabled=false;}});
function showOtp(){document.querySelector('#otpBox')?.remove();const section=document.createElement('section');section.id='otpBox';section.className='otpbox';const text=document.createElement('p');text.textContent='กรอกรหัส OTP 6 หลักที่ส่งไป '+pending.email+' (ใช้ได้ภายใน 10 นาที)';const otpForm=document.createElement('form');const label=document.createElement('label');label.htmlFor='otp';label.textContent='รหัสยืนยัน';const input=document.createElement('input');input.id='otp';input.required=true;input.pattern='[0-9]{6}';input.maxLength=6;input.inputMode='numeric';input.autocomplete='one-time-code';const verify=document.createElement('button');verify.type='submit';verify.textContent='ยืนยันอีเมลและเข้าสู่ระบบ →';const back=document.createElement('button');back.type='button';back.className='light';back.textContent='แก้ไขอีเมล / ขอรหัสใหม่';otpForm.append(label,input,verify);section.append(text,otpForm,back);form.hidden=true;feedback.after(section);input.focus();back.addEventListener('click',()=>{if(busy)return;section.remove();form.hidden=false;feedback.textContent='หากขอรหัสอีกครั้ง กรุณารออย่างน้อย 60 วินาที';});otpForm.addEventListener('submit',async event=>{event.preventDefault();if(busy||!otpForm.reportValidity())return;busy=true;verify.disabled=true;back.disabled=true;feedback.textContent='กำลังยืนยันรหัส…';try{const session=await api('verifyOtp',{email:pending.email,otp:input.value});if(!session?.token||!session.user)throw Error('รูปแบบข้อมูลตอบกลับไม่ถูกต้อง');sessionStorage.setItem('vc-session',JSON.stringify(session));window.location.replace('index.html');}catch(error){feedback.textContent=error.message;}finally{busy=false;verify.disabled=false;back.disabled=false;}});}
document.querySelector('#signup')?.addEventListener('click',()=>{location.href='register.html';});document.querySelector('#closeDialog')?.addEventListener('click',()=>document.querySelector('#status').close());
